create temporary table proof as select '{"stage":"concerns","section":6,"intake":{"firstName":"Quality","lastName":"Review","email":"quality@example.com","mobilePhone":"555-0100","streetAddress":"1 Main St","city":"Orlando","stateProvince":"FL","postalCode":"32801","country":"United States","occupationTitle":"Executive","ownedBusinessBefore":"no","exploredFranchiseBefore":"yes","preferredContactMethod":"email","bestContactTime":"morning"},"answers":{"q1":["Build long-term wealth"],"q3":["I''m earning the income I wanted"],"q4":["Not important"],"q5":["Closely involved in day-to-day operations"],"q6":["I''d welcome it if I were building something of my own"],"q7":["I want clear ownership and prefer to be personally accountable for the outcome"],"q8":["Step in and handle the work myself"],"q9":["Developing employees"],"q10":["Developing employees"],"q11":["Understand the reasoning and consider whether I should adjust"],"q12":["Follow the system as designed until I understand it thoroughly"],"q13":["Very uncomfortable"],"q14":["Energized by it"],"q15":["Networking and referrals"],"q16":["Give them space and wait"],"q17":["Very uncomfortable"],"q18":["Build one strong business that provides excellent income"],"q19":["Continue researching until most uncertainty is eliminated"],"q20":["Detailed financial analysis"],"q22":["Analyze what happened and adjust my approach"],"q23":["Study the numbers, identify the problem and adjust"],"q24":["Prefer predictability even if it limits upside"],"q25":["Businesses and executives"],"q26":["Home-based or remote"],"q27":["Enjoy building and leading larger teams"],"q28":["Professional salaried employees"],"q29":["Primarily weekday/business hours"],"q30":["Selling would remain a major part of my role"],"q31":["Large number of employees"],"q32":["Under $100,000"],"q33":["Under $25,000"],"q34":["Under $50,000"],"q35":["Less than 3 months"],"q2":["Build long-term wealth"],"q21":["Detailed financial analysis"],"q36-geography":["Need to remain near my current location"],"q36-stakeholders":["Decision is primarily mine"],"q36-stage":["Actively researching franchises"],"concerns":["I don''t have a major concern right now"]},"consent":true,"startedAt":"2026-09-08T12:00:00Z"}'::jsonb p, '{"version":"franchise-ownership-v1","instrumentVersion":"conference-assessment-v1","analysisVersion":2,"evidence":[{"id":"ev-q1-1","questionId":"q1","category":"motivation","dimension":"ownershipMotivation","statement":"Build long-term wealth","strength":0.8,"confidence":1},{"id":"ev-q5-2","questionId":"q5","category":"preference","dimension":"ownerRole","statement":"Preferred owner role: Closely involved in day-to-day operations","strength":0.8,"confidence":1},{"id":"ev-q13-3","questionId":"q13","category":"capability","dimension":"businessDevelopmentCapability","statement":"Prospecting comfort: Very uncomfortable","strength":0.8,"confidence":1},{"id":"ev-q14-4","questionId":"q14","category":"preference","dimension":"businessDevelopmentAppetite","statement":"Launch-stage sales appetite: Energized by it","strength":0.8,"confidence":1},{"id":"ev-q27-5","questionId":"q27","category":"preference","dimension":"employeeAppetite","statement":"Staffing preference: Enjoy building and leading larger teams","strength":0.8,"confidence":1},{"id":"ev-q12-6","questionId":"q12","category":"preference","dimension":"systemAlignment","statement":"System response: Follow the system as designed until I understand it thoroughly","strength":0.8,"confidence":1},{"id":"ev-q35-7","questionId":"q35","category":"constraint","dimension":"householdRunway","statement":"Household runway: Less than 3 months","strength":0.8,"confidence":1},{"id":"ev-q33-8","questionId":"q33","category":"constraint","dimension":"liquidCapital","statement":"Candidate-reported liquid capital: Under $25,000","strength":0.8,"confidence":1}],"dimensions":{"businessDevelopmentCapability":42,"businessDevelopmentAppetite":100,"leadershipCapability":55,"employeeAppetite":100,"systemAlignment":100,"independentJudgment":0,"riskTolerance":0,"resilience":85,"incomeUrgency":0,"growthOrientation":55,"relationshipOrientation":88,"operatingInvolvement":90,"executionOrientation":88,"assetOrientation":88,"delegationOrientation":25,"strategicOwnerPreference":35,"communityVisibility":0},"tensions":[],"discoveryPriorities":[{"title":"Owner-Led Sales","whyItMatters":"Launch and mature-stage selling preferences should align with the customer-acquisition model.","suggestedQuestion":"What role are you willing to personally play in customer acquisition during the first 18–24 months?","evidenceRefs":["q13","q14","q15","q30"],"priority":"normal","confidence":1},{"title":"Franchise-System Autonomy","whyItMatters":"The right model should balance operating playbooks with room for judgment.","suggestedQuestion":"Where do you want clear franchisor direction, and where do you need latitude to make your own decisions?","evidenceRefs":["q11","q12"],"priority":"normal","confidence":0.75},{"title":"Staffing Model","whyItMatters":"Team scale and management intensity shape the owner''s daily work.","suggestedQuestion":"What size and type of team would you still want to lead after the business is established?","evidenceRefs":["q7","q8","q27","q28"],"priority":"normal","confidence":1}],"opportunityCharacteristics":[{"characteristic":"B2B","disposition":"Attractive","reason":"The candidate expressed openness to serving businesses and executives."},{"characteristic":"B2C","disposition":"Acceptable","reason":"No strong consumer preference surfaced; validate customer fit rather than assuming it."},{"characteristic":"relationship-led","disposition":"Attractive","reason":"Preferred acquisition approaches emphasize networking and referrals."},{"characteristic":"owner selling","disposition":"Attractive","reason":"Keeps demonstrated capability separate from willingness to sell."},{"characteristic":"lean team","disposition":"Acceptable","reason":"A lean team may fit, although the candidate did not require minimal staffing."},{"characteristic":"employee-intensive","disposition":"Attractive","reason":"Reflects preferred workforce scale, not leadership ability."},{"characteristic":"manager-led","disposition":"Potential Constraint","reason":"The desired owner role emphasizes personal involvement; validate whether a manager-led model supports or conflicts with that preference."},{"characteristic":"owner-operated","disposition":"Attractive","reason":"Reflects desired day-to-day involvement."},{"characteristic":"home-based","disposition":"Attractive","reason":"Reflects selected operating environments."},{"characteristic":"retail","disposition":"Validate","reason":"Combines operating-environment interest with stated exclusions."},{"characteristic":"business-hours","disposition":"Attractive","reason":"Reflects stated schedule preferences."},{"characteristic":"scalable territories","disposition":"Acceptable","reason":"Reflects growth and expansion orientation."},{"characteristic":"franchise-system intensive","disposition":"Attractive","reason":"The candidate is willing to operate within the system while preserving constructive dialogue: Follow the system as designed until I understand it thoroughly."},{"characteristic":"fast ramp","disposition":"Acceptable","reason":"Income timing requires validation against business economics and household runway."},{"characteristic":"stated investment range","disposition":"Acceptable","reason":"Uses stated comfort independently from reported capacity."}],"consultantBrief":{"ownershipOrientation":{"text":"The candidate appears oriented toward closely involved in day-to-day operations, with a growth preference to build one strong business that provides excellent income.","evidenceRefs":["q5","q18"]},"whatStandsOut":[{"text":"The candidate wants meaningful operating involvement while also protecting schedule or family flexibility, making the sustainable day-to-day owner role important to validate.","evidenceRefs":["q5","q29"]}],"validateDuringDiscovery":[{"text":"Launch and mature-stage selling preferences should align with the customer-acquisition model.","evidenceRefs":["q13","q14","q15","q30"]},{"text":"The right model should balance operating playbooks with room for judgment.","evidenceRefs":["q11","q12"]},{"text":"Team scale and management intensity shape the owner''s daily work.","evidenceRefs":["q7","q8","q27","q28"]}],"decisionDynamics":{"text":"The primary concern is i don''t have a major concern right now; the candidate''s decision approach is to continue researching until most uncertainty is eliminated.","evidenceRefs":["concerns","q19"]},"financialContext":{"text":"Candidate-reported liquidity (Under $25,000) and stated investment comfort (Under $50,000) are separate inputs. Funding structure, total project cost, and comfort with capital at risk remain Discovery topics; no qualification is implied.","evidenceRefs":["q32","q33","q34"]},"startDiscoveryHere":{"text":"What would meaningful day-to-day involvement look like without sacrificing the schedule flexibility that matters to you?","evidenceRefs":["q5","q29"]}},"evidenceDetails":[{"topic":"ownership motivation","response":"Build long-term wealth","interpretation":"What is driving you to explore business ownership right now?","questionId":"q1"},{"topic":"preferred owner role","response":"Closely involved in day-to-day operations","interpretation":"Which statement comes closest to the role you''d ideally like to have in your business?","questionId":"q5"},{"topic":"schedule preferences","response":"Primarily weekday/business hours","interpretation":"Which schedule characteristics matter to you?","questionId":"q29"},{"topic":"prospecting comfort","response":"Very uncomfortable","interpretation":"How comfortable are you initiating a business conversation with someone you''ve never met?","questionId":"q13"},{"topic":"launch-stage sales appetite","response":"Energized by it","interpretation":"Suppose your business required you personally to develop new customer relationships every week for the first two years. How would you feel?","questionId":"q14"},{"topic":"business-development style","response":"Networking and referrals","interpretation":"Which types of business development feel most natural to you?","questionId":"q15"},{"topic":"mature-stage sales appetite","response":"Selling would remain a major part of my role","interpretation":"How much personal selling would you ideally want to perform once the business is established?","questionId":"q30"},{"topic":"feedback receptivity","response":"Understand the reasoning and consider whether I should adjust","interpretation":"When someone gives you constructive feedback that challenges your approach, what is your natural first reaction?","questionId":"q11"},{"topic":"franchise-system alignment","response":"Follow the system as designed until I understand it thoroughly","interpretation":"You join a franchise system and discover a process you believe could be improved. What would you most likely do?","questionId":"q12"},{"topic":"accountability and leadership","response":"I want clear ownership and prefer to be personally accountable for the outcome","interpretation":"When you''re responsible for an important result, which statement sounds most like you?","questionId":"q7"},{"topic":"people-management behavior","response":"Step in and handle the work myself","interpretation":"A capable employee repeatedly misses an important performance expectation. What are you most likely to do first?","questionId":"q8"},{"topic":"employee appetite","response":"Enjoy building and leading larger teams","interpretation":"How do you feel about managing employees?","questionId":"q27"},{"topic":"workforce tolerance","response":"Professional salaried employees","interpretation":"Which workforce types would you be comfortable managing?","questionId":"q28"}],"ownershipProfile":{"primary":"Team-Building Leader","supporting":["Executive Business Developer","Hands-On Business Operator"],"confidence":0.92,"confidenceState":"High Confidence","interpretation":"You appear to value active ownership and meaningful growth while also wanting a schedule that remains workable over time.","motivations":["Build long-term wealth"],"operatingPreferences":["Closely involved in day-to-day operations","Primarily weekday/business hours"],"strengths":["Takes personal accountability for important outcomes","Approaches significant decisions thoughtfully","Learns from setbacks and adapts the approach"],"characteristics":["B2B","relationship-led","owner selling","employee-intensive","owner-operated","home-based","business-hours","franchise-system intensive"],"consultantQuestions":["What role are you willing to personally play in customer acquisition during the first 18–24 months?","Where do you want clear franchisor direction, and where do you need latitude to make your own decisions?","What size and type of team would you still want to lead after the business is established?"]},"executiveSummary":"The responses most closely reflect a Team-Building Leader. Discovery should focus on owner-led sales, franchise-system autonomy, staffing model.","financial":{"netWorth":"Under $100,000","liquidCapital":"Under $25,000","investmentRange":"Under $50,000","disclaimer":"Candidate-reported and not independently verified by FranGroove."}}'::jsonb a;
grant select on proof to anon,authenticated,service_role;
-- Keep the independent concurrency fixture older than the assessment under test. now() is constant within this transaction.
insert into public.assessment_sessions(organization_id,candidate_id,owning_membership_id,created_by_membership_id,token_hash,expires_at,created_at) select organization_id,candidate_id,owning_membership_id,created_by_membership_id,repeat('e',64),now()+interval '14 days',now()-interval '3 days' from public.assessment_sessions where token_hash=repeat('a',64);
select ok(to_regprocedure('public.submit_assessment(text,jsonb,jsonb,jsonb,integer)') is null,'unsafe overload removed');
select ok(not has_function_privilege('anon','public.finalize_assessment_trusted(text,jsonb,jsonb)','execute'),'anon cannot finalize');
select ok(not has_function_privilege('authenticated','public.finalize_assessment_trusted(text,jsonb,jsonb)','execute'),'ordinary user cannot forge analysis');
select ok(has_function_privilege('service_role','public.finalize_assessment_trusted(text,jsonb,jsonb)','execute'),'trusted server can finalize');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join lateral aclexplode(p.proacl) a where n.nspname in ('public','private') and p.proname in ('load_assessment_by_token','save_assessment_progress','finalize_assessment_trusted','validate_assessment_progress','assessment_response_contract','create_assessment_candidate') and a.grantee=0),'no PUBLIC function grants');
select ok(not has_function_privilege('anon','public.create_assessment_candidate(uuid,text,text,text,text)','execute'),'anon cannot create candidates');
set local role anon;
select is(public.load_assessment_by_token(repeat('a',64))->>'status','invited','valid token opens');
select ok(public.load_assessment_by_token(repeat('d',64)) is null,'unknown token unavailable');
select ok(public.load_assessment_by_token('malformed') is null,'malformed token unavailable');
select ok(public.load_assessment_by_token(repeat('b',64)) is null,'expired token unavailable');
select ok(public.load_assessment_by_token(repeat('c',64)) is null,'revoked token unavailable');
select ok(not (public.load_assessment_by_token(repeat('a',64)) ?| array['candidate_id','organization_id','token_hash','analysis_snapshot']),'public DTO omits internals');
select lives_ok($q$select public.save_assessment_progress(repeat('a',64),(select p from proof))$q$,'permitted progress saves');
select is(public.load_assessment_by_token(repeat('a',64))->'progress_snapshot',(select p from proof),'progress resumes exactly');
select ok(public.load_assessment_by_token(repeat('e',64))->'progress_snapshot'='null'::jsonb,'other active token remains untouched');
select throws_ok($q$select public.save_assessment_progress(repeat('a',64),(select jsonb_set(p,'{stage}','null') from proof))$q$,'22023',null,'null stage rejected');
select throws_ok($q$select public.save_assessment_progress(repeat('a',64),'{}')$q$,'22023',null,'empty progress rejected');
select throws_ok($q$select public.save_assessment_progress(repeat('a',64),(select p||'{"organization_id":"other"}'::jsonb from proof))$q$,'22023',null,'protected metadata rejected');
select throws_ok($q$select public.save_assessment_progress(repeat('a',64),(select jsonb_set(p,'{answers,q1}','"bad"') from proof))$q$,'22023',null,'scalar answer rejected');
select throws_ok($q$select public.save_assessment_progress(repeat('a',64),(select jsonb_set(p,'{answers,q1}','["unsupported"]') from proof))$q$,'22023',null,'unknown option rejected');
select throws_ok($q$select public.finalize_assessment_trusted(repeat('a',64),(select p from proof),(select a from proof))$q$,'42501',null,'anonymous analysis rejected by actual execution');
select throws_ok($q$select public.save_assessment_progress(repeat('b',64),(select p from proof))$q$,'42501',null,'expired token cannot save');
reset role;
select ok((select progress_snapshot is null from public.assessment_sessions where token_hash=repeat('b',64)),'other token remains untouched');
set local role service_role;
select throws_ok($q$select public.finalize_assessment_trusted(repeat('a',64),(select p from proof),'{}')$q$,'22023',null,'missing trusted output rejects atomically');
reset role;
select is((select count(*) from public.assessment_submissions where session_id='53000000-0000-0000-0000-000000000001'),0::bigint,'failed finalization creates no submission');
-- Force a failure after submission evidence is inserted to prove transaction rollback.
create function pg_temp.reject_analysis_insert() returns trigger language plpgsql as $$begin raise exception 'local atomicity test'; end$$;
create trigger local_reject_analysis before insert on public.assessment_analyses for each row execute function pg_temp.reject_analysis_insert();
set local role service_role;
select throws_ok($q$select public.finalize_assessment_trusted(repeat('a',64),(select p from proof),(select a from proof))$q$,'P0001','local atomicity test','analysis insert failure rolls back finalization');
reset role;
select is((select count(*) from public.assessment_submissions where session_id='53000000-0000-0000-0000-000000000001'),0::bigint,'inserted submission is rolled back with analysis failure');
select is((select status::text from public.assessment_sessions where token_hash=repeat('a',64)),'in-progress','failed transaction leaves session incomplete');
drop trigger local_reject_analysis on public.assessment_analyses;
set local role service_role;
select is(public.finalize_assessment_trusted(repeat('a',64),(select p from proof),(select a from proof))->>'status','analyzed','trusted finalization completes');
select is(public.finalize_assessment_trusted(repeat('a',64),(select p from proof),(select a from proof))->>'status','analyzed','same retry is idempotent');
select throws_ok($q$select public.finalize_assessment_trusted(repeat('a',64),(select jsonb_set(p,'{intake,firstName}','"Changed"') from proof),(select a from proof))$q$,'55000',null,'altered retry rejected');
reset role;
select is((select count(*) from public.assessment_submissions where session_id='53000000-0000-0000-0000-000000000001'),1::bigint,'one immutable submission');
select is((select count(*) from public.assessment_analyses where session_id='53000000-0000-0000-0000-000000000001'),1::bigint,'one analysis');
select is((select analysis_snapshot from public.assessment_analyses where session_id='53000000-0000-0000-0000-000000000001'),(select a from proof),'existing deterministic analysis preserved');
select throws_ok($q$update public.assessment_submissions set intake_snapshot='{}' where session_id='53000000-0000-0000-0000-000000000001'$q$,'55000',null,'submitted evidence immutable');
set local role anon;
select throws_ok($q$select public.save_assessment_progress(repeat('a',64),(select p from proof))$q$,'42501',null,'completed progress immutable');
select ok(not ((public.load_assessment_by_token(repeat('a',64))->'candidate_analysis') ?| array['consultantBrief','dimensions','tensions','discoveryPriorities','executiveSummary']),'consultant analysis absent');
select ok(public.load_assessment_by_token(repeat('a',64))->'candidate_analysis'->'ownershipProfile' is not null,'candidate completion profile remains available');
select throws_ok($q$select * from public.get_candidate_assessment('cand_reportauthaaaaaa')$q$,'42501',null,'anon denied consultant RPC');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','50000000-0000-0000-0000-000000000002',true);
select is((select status::text from public.get_candidate_assessment('cand_reportauthaaaaaa')),'analyzed','owning consultant sees completion');
select is((select analysis_snapshot from public.get_candidate_assessment('cand_reportauthaaaaaa')),(select a from proof),'consultant sees authoritative intelligence');
select set_config('request.jwt.claim.sub','50000000-0000-0000-0000-000000000004',true);
select is((select count(*) from public.get_candidate_assessment('cand_reportauthaaaaaa')),0::bigint,'other tenant cannot read intelligence');
select is((select count(*) from public.assessment_submissions where session_id='53000000-0000-0000-0000-000000000001'),0::bigint,'RLS hides submissions from other tenant');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','50000000-0000-0000-0000-000000000002',true);
select lives_ok($q$select * from public.create_assessment_candidate('50000000-0000-0000-0000-000000000100','New','Candidate',' Retry@Example.test ','4075550199')$q$,'normal creation uses the existing candidate model');
select lives_ok($q$select * from public.create_assessment_candidate('50000000-0000-0000-0000-000000000100','Changed','Name','retry@example.test','')$q$,'normalized retry resolves existing identity');
select is((select count(*) from public.candidates where email='retry@example.test'),1::bigint,'retry does not duplicate candidate');
select is((select first_name from public.candidates where email='retry@example.test'),'New','retry preserves existing identity');
select throws_ok($q$select * from public.create_assessment_candidate('50000000-0000-0000-0000-000000000200','Other','Tenant','retry@example.test','')$q$,'42501',null,'cannot create in another tenant');
reset role;
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='submit_assessment'),'no unsafe submit overload remains');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.proname in ('load_assessment_by_token','save_assessment_progress','finalize_assessment_trusted','validate_assessment_progress','assessment_response_contract','create_assessment_candidate') and not ('search_path=""'=any(p.proconfig))),'all new RPC search paths are empty');
set local role anon;
select throws_ok($q$select public.save_assessment_progress(repeat('e',64),(select p||'{"analysis":{}}'::jsonb from proof))$q$,'22023',null,'caller analysis field rejected');
select throws_ok($q$select public.save_assessment_progress(repeat('c',64),(select p from proof))$q$,'42501',null,'revoked token cannot save');
reset role;
set local role service_role;
select throws_ok($q$select public.finalize_assessment_trusted(repeat('b',64),(select p from proof),(select a from proof))$q$,'42501',null,'expired token cannot finalize');
select throws_ok($q$select public.finalize_assessment_trusted(repeat('c',64),(select p from proof),(select a from proof))$q$,'42501',null,'revoked token cannot finalize');
reset role;
select * from finish();
rollback;
